@@ -0,0 +1,56 @@
+import 'dart:async';
+
+import 'package:app_workflow_task_fixture/data/task_repository.dart';
+import 'package:app_workflow_task_fixture/model/task.dart';
+import 'package:app_workflow_task_fixture/state/task_controller.dart';
+import 'package:flutter_test/flutter_test.dart';
+
+class _Api implements TaskApi {
+  final requests = <String>[];
+  final responses = <Completer<Map<String, Object?>>>[];
+
+  @override
+  Future<Map<String, Object?>> completeTask(String id) {
+    requests.add(id);
+    final response = Completer<Map<String, Object?>>();
+    responses.add(response);
+    return response.future;
+  }
+}
+
+void main() {
+  test(
+    'unconfirmed completion retains server fields and permits retry',
+    () async {
+      final api = _Api();
+      final controller = TaskController(
+        TaskRepository(api),
+        const Task(id: 'original', title: 'Original', completed: false),
+      );
+      addTearDown(controller.dispose);
+
+      final first = controller.complete();
+      api.responses.single.complete({
+        'id': 'confirmed',
+        'title': 'Still open',
+        'completed': false,
+      });
+      await first;
+      expect(controller.task.title, 'Still open');
+      expect(controller.task.completed, isFalse);
+      expect(controller.saving, isFalse);
+
+      final retry = controller.complete();
+      expect(api.requests, ['original', 'confirmed']);
+      api.responses.last.complete({
+        'id': 'confirmed',
+        'title': 'Done',
+        'completed': true,
+      });
+      await retry;
+      await controller.complete();
+      expect(api.requests, ['original', 'confirmed']);
+      expect(controller.task.title, 'Done');
+    },
+  );
+}
